// The policy table is the whole input: one row per product line.
const cfg = $('Settings').first().json;

const rows = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && String(r.keyword || '').trim(); });

if (!rows.length) {
  throw new Error('The map_policy data table is empty. Add a row with keyword, brand, map_price and authorized_sellers.');
}

const cap = Math.max(1, Math.min(25, Number(cfg.max_terms) || 8));
const chosen = rows.slice(0, cap);

// The policy travels alongside the search so the comparison later does not have
// to re-read the sheet - the snapshot comes back keyed by keyword, nothing else.
const policy = chosen.map(function (r) {
  return {
    keyword: String(r.keyword).trim(),
    brand: String(r.brand || '').trim(),
    map_price: Number(String(r.map_price || '').replace(/[^0-9.]/g, '')) || 0,
    // A keyword search returns a product line, not one product, and a floor is
    // per product. Naming the ASINs the floor covers keeps a $20 model in the
    // same line from being reported as 64% under the flagship's price. Leave it
    // empty and the floor applies to everything the brand match catches.
    asins: String(r.asins || '')
      .split(/[|,;\s]+/)
      .map(function (x) { return x.trim().toUpperCase(); })
      .filter(Boolean),
    authorized: String(r.authorized_sellers || '')
      .split(/[|,;]+/)
      .map(function (s) { return s.trim().toLowerCase(); })
      .filter(Boolean),
  };
});

// One item per product line. Each line is searched on its own below, so a
// term that Amazon chokes on costs that line and not the whole run.
return policy.map(function (p) { return { json: p }; });

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, and neverError means nothing throws. Unchecked, snapshot_id is
// undefined, the progress URL becomes .../progress/undefined, and the failure
// surfaces two nodes later blaming the wrong node.
//
// single-item input: one trigger call returns one snapshot id.
const body = $input.first().json;

if (body && body.error) {
  throw new Error('Bright Data refused the search: ' + body.error + ' (' + (body.code || 'no code') + ')');
}
if (!body || !body.snapshot_id) {
  throw new Error('No snapshot_id came back. Check the Bright Data credential and that the account has credits.');
}

return [{ json: { snapshot_id: body.snapshot_id } }];

// $runIndex is how many times this node has run, which on a loop is the poll
// count. Without a cap a stuck snapshot polls all night.
//
// single-item input: the progress endpoint returns one status object.
const cfg = $('Settings').first().json;
const body = $input.first().json || {};
const polls = $runIndex + 1;
const cap = Math.max(3, Math.min(60, Number(cfg.max_polls) || 20));

if (body.status === 'failed') {
  throw new Error('Bright Data reported the snapshot as failed: ' + JSON.stringify(body).slice(0, 300));
}
if (body.status !== 'ready' && polls >= cap) {
  throw new Error('Amazon was still running after ' + polls + ' polls on this line. Raise max_polls or cut results_per_term.');
}

return [{ json: { status: body.status || 'running', polls: polls } }];

// One row per offer, not one per product. The buy box is an offer like any
// other, and the interesting ones are almost always the second and third.
//
// include_errors=true puts error rows in the snapshot, so anything without an
// asin is dropped before it can be counted as a clean listing.
// The line being searched right now, taken off the loop rather than from a
// list index - a snapshot that came back empty must not shift the pairing.
const line_policy = $('One Product Line At A Time').first().json;

const offers = [];
const unread = [];

function money(v) {
  const n = Number(String(v === null || v === undefined ? '' : v).replace(/[^0-9.]/g, ''));
  return isFinite(n) && n > 0 ? n : 0;
}

for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.asin) { continue; }

  const line = {
    asin: r.asin,
    title: String(r.title || r.title_clean || '').slice(0, 140),
    url: r.url || ('https://www.amazon.com/dp/' + r.asin),
    brand: String(r.brand || ''),
    manufacturer: String(r.manufacturer || ''),
    keyword: (r.discovery_input && r.discovery_input.keyword) || '',
    list_price: money(r.initial_price) || money(r.final_price),
  };

  const box = money(r.final_price) || money(r.buybox_prices && r.buybox_prices.final_price);
  const boxSeller = String(r.buybox_seller || r.seller_name || '').trim();
  if (box && boxSeller) {
    offers.push(Object.assign({}, line, {
      seller: boxSeller,
      price: box,
      ships_from: String(r.ships_from || ''),
      is_buybox: true,
    }));
  }

  // Measured 2026-08-30: this array is null on half the rows and holds two
  // sellers on rows whose number_of_sellers reads 1. Null is "not returned",
  // which is a different answer from "nobody else is selling this".
  const others = Array.isArray(r.other_sellers_prices) ? r.other_sellers_prices : null;
  if (!others) {
    unread.push(r.asin);
    continue;
  }
  for (const o of others) {
    const p = money(o && o.price);
    const s = String((o && o.seller_name) || '').trim();
    if (!p || !s) { continue; }
    if (s.toLowerCase() === boxSeller.toLowerCase() && p === box) { continue; }
    offers.push(Object.assign({}, line, {
      seller: s,
      price: p,
      ships_from: String((o && o.ships_from) || ''),
      seller_rating: Number((o && o.seller_rating) || 0),
      is_buybox: false,
    }));
  }
}

return [{ json: {
  policy: line_policy,
  offers: offers,
  unread: unread,
  offer_count: offers.length,
}}];

// Two independent tests per offer: is this seller on the list, and is this
// price under the floor. An offer can fail both, and the digest says so.
//
// Input is one item per product line, collected by the loop above. Each carries
// its own policy, so nothing here has to guess which floor applies to which
// listing.
const cfg = $('Settings').first().json;
const lines = $input.all().map(function (i) { return i.json || {}; });

const tolerance = Math.max(0, Number(cfg.price_tolerance_percent) || 0) / 100;

function belongs(offer, p) {
  const hay = (offer.brand + ' ' + offer.manufacturer + ' ' + offer.title).toLowerCase();
  // brand and manufacturer disagree in the same row - Soundcore against Anker -
  // so the name is looked for across both plus the title rather than in one field.
  return p.brand ? hay.indexOf(p.brand.toLowerCase()) >= 0 : true;
}

const breaches = [];
const unread = [];
let checked = 0;

for (const line of lines) {
  const p = line.policy || {};
  const authorized = p.authorized || [];

  for (const asin of line.unread || []) { unread.push(asin); }

  for (const offer of line.offers || []) {
    if (!belongs(offer, p)) { continue; }
    checked += 1;

    const seller = String(offer.seller || '').toLowerCase();
    // Seller names are matched on a prefix, because a storefront listed as
    // "AnkerDirect" on the buy box appears as "AnkerDirect US" in the offer
    // array often enough that equality alone raises false breaches.
    const known = authorized.some(function (a) {
      return seller === a || seller.indexOf(a) === 0 || a.indexOf(seller) === 0;
    });

    // The floor only applies to the products it was written for. Everything
    // else the brand match caught is still checked for who is selling it.
    const priced = !(p.asins || []).length || p.asins.indexOf(String(offer.asin).toUpperCase()) >= 0;
    const floor = priced && p.map_price ? p.map_price * (1 - tolerance) : 0;
    const under = floor > 0 && offer.price < floor;
    if (known && !under) { continue; }

    const gap = under ? Math.round((p.map_price - offer.price) * 100) / 100 : 0;
    breaches.push({
      checked_at: new Date().toISOString().slice(0, 10),
      keyword: p.keyword || '',
      asin: offer.asin,
      title: offer.title,
      seller: offer.seller,
      price: offer.price,
      map_price: priced ? (p.map_price || '') : '',
      gap: under ? gap : '',
      gap_percent: under && p.map_price ? Math.round((gap / p.map_price) * 1000) / 10 : '',
      problem: !known && under ? 'unauthorised seller under your floor'
        : !known ? 'seller not on your list'
        : 'priced under your floor',
      on_buybox: offer.is_buybox ? 'yes' : 'no',
      url: offer.url,
    });
  }
}

breaches.sort(function (a, b) { return (Number(b.gap) || 0) - (Number(a.gap) || 0); });

const shown = breaches.slice(0, 15).map(function (b) {
  const price = '$' + Number(b.price).toFixed(2);
  const detail = b.gap ? (price + ' against your ' + b.map_price + ' floor, ' + b.gap_percent + '% under') : price;
  return '- *' + b.seller + '* on ' + b.asin + ': ' + detail + '\n  ' + b.problem + ' - ' + b.url;
});

let message = '*Amazon price policy: ' + breaches.length + ' breach' + (breaches.length === 1 ? '' : 'es') + ' across ' + checked + ' offers*\n\n' + shown.join('\n');
if (breaches.length > shown.length) {
  message += '\n\n...and ' + (breaches.length - shown.length) + ' more in the sheet.';
}
if (unread.length) {
  message += '\n\n' + unread.length + ' listing(s) came back without an offer list, so their other sellers are unknown: ' + unread.slice(0, 8).join(', ') + '.';
}

// A filtering step that can return zero items ends the branch, and the quiet
// path below it would never run. One marker item always comes back.
return [{ json: {
  has_breaches: breaches.length > 0,
  breaches: breaches,
  offers_checked: checked,
  unread: unread.length,
  chat_id: cfg.telegram_chat_id,
  message: message,
}}];

// The data table insert emits one item per breach row. Without executeOnce this
// would build the digest once per row and Telegram would receive it N times.
//
// single-item input: the digest was already assembled upstream; this reads it
// back rather than rebuilding it from the per-row items now in flight.
const found = $('Find The Breaches').first().json;

return [{ json: {
  chat_id: found.chat_id,
  message: found.message,
  breaches: found.breaches.length,
}}];
